import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.orderCustomFields().listOrderCustomFields(
        Map.of("sort", "label", "dir", "asc"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("order_custom_fields")) {
    Map<?, ?> field = (Map<?, ?>) row;
    System.out.println(field.get("id") + " " + field.get("label") + " " + field.get("field_type"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

